# Try partition: A={0,1,2}, B={3,4,5}, C={6,7,8}, D={9,10,11}
classes = {0:'A',1:'A',2:'A',3:'B',4:'B',5:'B',6:'C',7:'C',8:'C',9:'D',10:'D',11:'D'}
fixed = [(0,10),(0,11),(0,7),(3,10),(2,9),(1,9),(3,6)]
for u,v in fixed:
    print(u,v,classes[u],classes[v], "OK" if classes[u]!=classes[v] else "BAD")

# Generate all edges between different classes
edges = []
for u in range(12):
    for v in range(u+1,12):
        if classes[u]!=classes[v]:
            edges.append((u,v))
print("num edges:", len(edges))

# verify
from itertools import combinations
E = set(edges)
# min degree
deg = [0]*12
for u,v in edges:
    deg[u]+=1; deg[v]+=1
print("min deg:",min(deg))
# check all fixed edges present
for e in fixed:
    assert e in E
print("all fixed present")
# max clique: check no K5
for combo in combinations(range(12),5):
    if all((min(a,b),max(a,b)) in E for a,b in combinations(combo,2)):
        print("K5 found!", combo); break
else:
    print("no K5")
print(edges)
